/**
 * @description Test class for WorkItemHoursCalculator
 * Tests hours calculation, rollup logic, and hierarchical updates
 * Refactored to use TestDataFactory for improved maintainability
 *
 * @group Tests
 * @date 2025-10-23
 */
@IsTest(SeeAllData=false)
private class WorkItemHoursCalculatorTest {
    private static final WorkItemHoursCalculator calculator;

    static {
        calculator = new WorkItemHoursCalculator();
    }

    @TestSetup
    static void setup() {
        // Use TestDataFactory for consistent test data creation
        Project_Template__c projectTemplate = TestDataFactory.createProjectTemplate();
        Work_Item_Template__c workItemTemplate = TestDataFactory.createWorkItemTemplate();
        Project__c project = TestDataFactory.createProject(projectTemplate.Id);

        // Create Resource Assignment using factory
        Resource_Assignment__c resourceAssignment = TestDataFactory.createResourceAssignment(project.Id);

        // Create hierarchical Work Items (3 levels)
        List<Work_Item__c> level0Items = new List<Work_Item__c>();
        for (Integer i = 0; i < 5; i++) {
            level0Items.add(
                new Work_Item__c(
                    Work_Item_Name__c = 'Milestone ' + i,
                    Project__c = project.Id,
                    Work_Item_Template__c = workItemTemplate.Id,
                    Status__c = 'In Progress',
                    Actual_Hours__c = 0
                )
            );
        }
        insert as user level0Items;

        // Level 1: Child items
        List<Work_Item__c> level1Items = new List<Work_Item__c>();
        for (Work_Item__c parent : level0Items) {
            for (Integer j = 0; j < 2; j++) {
                level1Items.add(
                    new Work_Item__c(
                        Work_Item_Name__c = parent.Work_Item_Name__c + ' - Deliverable ' + j,
                        Project__c = project.Id,
                        Work_Item_Template__c = workItemTemplate.Id,
                        Parent_Work_Item__c = parent.Id,
                        Status__c = 'In Progress',
                        Actual_Hours__c = 0
                    )
                );
            }
        }
        insert as user level1Items;

        // Level 2: Grandchild items
        List<Work_Item__c> level2Items = new List<Work_Item__c>();
        for (Work_Item__c parent : level1Items) {
            for (Integer k = 0; k < 3; k++) {
                level2Items.add(
                    new Work_Item__c(
                        Work_Item_Name__c = parent.Work_Item_Name__c + ' - Task ' + k,
                        Project__c = project.Id,
                        Work_Item_Template__c = workItemTemplate.Id,
                        Parent_Work_Item__c = parent.Id,
                        Status__c = 'In Progress',
                        Actual_Hours__c = 0
                    )
                );
            }
        }
        insert as user level2Items;

        // Create time entries for leaf items (tasks) - 5 hours each
        List<Time_Entry__c> timeEntries = new List<Time_Entry__c>();
        for (Work_Item__c task : level2Items) {
            timeEntries.add(
                new Time_Entry__c(
                    Work_Item__c = task.Id,
                    Project__c = project.Id,
                    Resource_Assignment__c = resourceAssignment.Id,
                    Hours__c = 5,
                    Description__c = 'Test time entry',
                    Date__c = TestDataFactory.getStartDate()
                )
            );
        }
        insert as user timeEntries;

        // Create time entries for level 1 items - 20 hours each
        List<Time_Entry__c> level1TimeEntries = new List<Time_Entry__c>();
        for (Work_Item__c deliverable : level1Items) {
            level1TimeEntries.add(
                new Time_Entry__c(
                    Work_Item__c = deliverable.Id,
                    Project__c = project.Id,
                    Resource_Assignment__c = resourceAssignment.Id,
                    Hours__c = 20,
                    Description__c = 'Test time entry',
                    Date__c = TestDataFactory.getStartDate()
                )
            );
        }
        insert as user level1TimeEntries;

        // Create time entries for level 0 items - 10 hours each
        List<Time_Entry__c> level0TimeEntries = new List<Time_Entry__c>();
        for (Work_Item__c milestone : level0Items) {
            level0TimeEntries.add(
                new Time_Entry__c(
                    Work_Item__c = milestone.Id,
                    Project__c = project.Id,
                    Resource_Assignment__c = resourceAssignment.Id,
                    Hours__c = 10,
                    Description__c = 'Test time entry',
                    Date__c = TestDataFactory.getStartDate()
                )
            );
        }
        insert as user level0TimeEntries;

        // Total: 5 + 10 + 30 = 45 work items
    }

    @IsTest
    static void testCalculateActualHoursLeafItem() {
        // Test leaf item (no children) - should equal Total_Logged_Hours__c
        Work_Item__c leafItem = [
            SELECT Id
            FROM Work_Item__c
            WHERE Work_Item_Name__c LIKE '%Task%'
            LIMIT 1
        ];

        Test.startTest();
        List<Work_Item__c> results = calculator.calculateActualHours(new Set<Id>{ leafItem.Id });
        Test.stopTest();

        // Verify result (leaf item has 5 hours from time entry)
        System.assertEquals(1, results.size(), 'Should return 1 result');
        System.assertEquals(5, results[0].Actual_Hours__c, 'Leaf item actual hours should equal total logged hours');

        // Verify database updated
        Work_Item__c updatedItem = [SELECT Actual_Hours__c FROM Work_Item__c WHERE Id = :leafItem.Id];
        System.assertEquals(5, updatedItem.Actual_Hours__c, 'Database should be updated');
    }

    @IsTest
    static void testCalculateActualHoursParentWithChildren() {
        // Get a level 1 item (has children)
        Work_Item__c parentItem = [
            SELECT Id
            FROM Work_Item__c
            WHERE Work_Item_Name__c LIKE '%Deliverable%'
            LIMIT 1
        ];

        // First calculate all children
        List<Work_Item__c> children = [SELECT Id FROM Work_Item__c WHERE Parent_Work_Item__c = :parentItem.Id];
        Set<Id> childRequests = new Set<Id>();
        for (Work_Item__c child : children) {
            childRequests.add(child.Id);
        }
        calculator.calculateActualHours(childRequests);

        // Now calculate parent
        Test.startTest();
        List<Work_Item__c> results = calculator.calculateActualHours(new Set<Id>{ parentItem.Id });
        Test.stopTest();

        // Parent should have: Total_Logged_Hours (20) + Sum of 3 children (3 × 5 = 15) = 35
        System.assertEquals(35, results[0].Actual_Hours__c, 'Parent actual hours should include children');

        // Verify database updated
        Work_Item__c updatedItem = [SELECT Actual_Hours__c FROM Work_Item__c WHERE Id = :parentItem.Id];
        System.assertEquals(35, updatedItem.Actual_Hours__c, 'Database should be updated with rollup');
    }

    @IsTest
    static void testCalculateActualHoursZeroHours() {
        // Create work item with no time entries (zero hours)
        Project__c project = [SELECT Id FROM Project__c LIMIT 1];
        Work_Item_Template__c template = [SELECT Id FROM Work_Item_Template__c LIMIT 1];

        Work_Item__c workItem = new Work_Item__c(
            Work_Item_Name__c = 'Item With Zero Hours',
            Project__c = project.Id,
            Work_Item_Template__c = template.Id,
