        Test.stopTest();

        System.assertEquals(0, results[0].Actual_Hours__c, 'Zero hours should remain zero');
    }

    @IsTest
    static void testBulkCalculation() {
        // Get all leaf items (tasks)
        List<Work_Item__c> leafItems = [
            SELECT Id
            FROM Work_Item__c
            WHERE Work_Item_Name__c LIKE '%Task%'
        ];

        Set<Id> requests = new Set<Id>();
        for (Work_Item__c item : leafItems) {
            requests.add(item.Id);
        }

        Test.startTest();
        List<Work_Item__c> results = calculator.calculateActualHours(requests);
        Test.stopTest();

        // Should have 30 results (5 milestones × 2 deliverables × 3 tasks)
        System.assertEquals(30, results.size(), 'Should process all 30 leaf items in bulk');

        // Verify all results have calculated hours
        for (Work_Item__c result : results) {
            System.assertNotEquals(null, result.Actual_Hours__c, 'Each result should have actual hours');
        }
    }

    @IsTest
    static void testAncestorUpdatesCascade() {
        // Get a grandchild item
        Work_Item__c grandchild = [
            SELECT Id, Parent_Work_Item__c, Parent_Work_Item__r.Parent_Work_Item__c
            FROM Work_Item__c
            WHERE Work_Item_Name__c LIKE '%Task 0'
            LIMIT 1
        ];

