        System.assertEquals(5, updatedGrandchild.Actual_Hours__c, 'Grandchild should be updated');

        // Verify parent (child) was also updated by cascade
        Work_Item__c updatedChild = [SELECT Actual_Hours__c FROM Work_Item__c WHERE Id = :childId];
        System.assertNotEquals(null, updatedChild.Actual_Hours__c, 'Parent should be updated by cascade');

        // Verify grandparent was also updated by cascade
        Work_Item__c updatedGrandparent = [SELECT Actual_Hours__c FROM Work_Item__c WHERE Id = :grandparentId];
        System.assertNotEquals(null, updatedGrandparent.Actual_Hours__c, 'Grandparent should be updated by cascade');
    }

