        insert as user level0;

        Work_Item__c level1 = new Work_Item__c(
            Work_Item_Name__c = 'Level 1',
            Project__c = project.Id,
            Work_Item_Template__c = template.Id,
            Parent_Work_Item__c = level0.Id,
            Status__c = 'In Progress'
        );
        insert as user level1;

        Work_Item__c level2 = new Work_Item__c(
            Work_Item_Name__c = 'Level 2',
            Project__c = project.Id,
            Work_Item_Template__c = template.Id,
            Parent_Work_Item__c = level1.Id,
            Status__c = 'In Progress'
        );
        insert as user level2;

        Work_Item__c level3 = new Work_Item__c(
