            Project__c = project.Id,
            Work_Item_Template__c = template.Id,
            Parent_Work_Item__c = level3.Id,
            Status__c = 'In Progress'
        );
        insert as user level4;

        // Create time entries for each level
        List<Time_Entry__c> timeEntries = new List<Time_Entry__c>();
        timeEntries.add(
            new Time_Entry__c(
                Work_Item__c = level0.Id,
                Project__c = project.Id,
                Resource_Assignment__c = resourceAssignment.Id,
                Hours__c = 1,
                Description__c = 'Level 0 hours',
                Date__c = Date.today()
            )
        );
        timeEntries.add(
            new Time_Entry__c(
                Work_Item__c = level1.Id,
                Project__c = project.Id,
                Resource_Assignment__c = resourceAssignment.Id,
                Hours__c = 2,
                Description__c = 'Level 1 hours',
                Date__c = Date.today()
            )
        );
        timeEntries.add(
            new Time_Entry__c(
                Work_Item__c = level2.Id,
                Project__c = project.Id,
                Resource_Assignment__c = resourceAssignment.Id,
                Hours__c = 3,
                Description__c = 'Level 2 hours',
                Date__c = Date.today()
            )
        );
        timeEntries.add(
            new Time_Entry__c(
                Work_Item__c = level3.Id,
                Project__c = project.Id,
                Resource_Assignment__c = resourceAssignment.Id,
                Hours__c = 4,
                Description__c = 'Level 3 hours',
                Date__c = Date.today()
            )
        );
        timeEntries.add(
            new Time_Entry__c(
                Work_Item__c = level4.Id,
                Project__c = project.Id,
                Resource_Assignment__c = resourceAssignment.Id,
                Hours__c = 5,
                Description__c = 'Level 4 hours',
                Date__c = Date.today()
            )
        );
        insert as user timeEntries;

        Test.startTest();
        calculator.calculateActualHours(new Set<Id>{ level4.Id });
        Test.stopTest();

        // Verify all levels updated
        // Level 4: 5
        // Level 3: 4 + 5 = 9
        // Level 2: 3 + 9 = 12
        // Level 1: 2 + 12 = 14
        // Level 0: 1 + 14 = 15

        Work_Item__c updatedLevel4 = [SELECT Actual_Hours__c FROM Work_Item__c WHERE Id = :level4.Id];
        System.assertEquals(5, updatedLevel4.Actual_Hours__c, 'Level 4 should have 5 hours');

        Work_Item__c updatedLevel0 = [SELECT Actual_Hours__c FROM Work_Item__c WHERE Id = :level0.Id];
        System.assertEquals(15, updatedLevel0.Actual_Hours__c, 'Level 0 should have cascaded total of 15 hours');
    }

    @IsTest
    static void testEmptyRequestList() {
        Test.startTest();
        List<Work_Item__c> results = calculator.calculateActualHours(new Set<Id>());
        Test.stopTest();

        // Should return empty list
        System.assertEquals(0, results.size(), 'Empty request should return empty results');
    }

    @IsTest
    static void testSecurityEnforcement() {
        // Verify WITH USER_MODE is applied in queries
        Work_Item__c workItem = [SELECT Id FROM Work_Item__c WHERE Work_Item_Name__c LIKE '%Task%' LIMIT 1];

        Id request = workItem.Id;

        Test.startTest();
        List<Work_Item__c> results = calculator.calculateActualHours(new Set<Id>{ request });
        Test.stopTest();

        // If user doesn't have access, operations should respect FLS
        // In this test context with admin access, we just verify the method runs without error
        System.assertNotEquals(null, results, 'Should return results when user has access');
    }
}

