/**
 * @description Trigger handler for Work_Item__c
 * Manages automatic sharing of Work Items with Project Resources
 * @author Claude Code
 * @date 2025-10-23
 */
public with sharing class WorkItemTriggerHandler extends TriggerHandler {
    private final WorkItemHoursCalculator CALCULATOR = new WorkItemHoursCalculator();
    private final UOW uow = new UOW(new List<SObjectType>{ Work_Item__c.SObjectType });

    protected override void afterInsert() {
        this.handleAfter();
    }

    protected override void afterUpdate() {
        this.handleAfter();
    }

    protected override void postRun(){
        this.uow.commitWork();
    }

    // Check for re-parenting to recalculate sharing
    private void handleAfter() {
        Set<Id> projectIds = new Set<Id>();
        Set<Id> calcRequests = new Set<Id>();

        for (Work_Item__c workItem : (List<Work_Item__c>) this.newList) {
            // If Parent Work Item changed, trigger sharing recalculation
            if (this.isChanged(workItem, Work_Item__c.Parent_Work_Item__c)) {
                projectIds.add(workItem.Project__c);
            }

            if (this.isChanged(workItem, Work_Item__c.Total_Logged_Hours__c)) {
                calcRequests.add(workItem.Id);
            }
        }

        if (!projectIds.isEmpty()) {
            // Re-run sharing logic for moved items
            SharingService.recalculateProjectSharing(projectIds);
        }

        if (!calcRequests.isEmpty()) {
            List<Work_Item__c> workItemsToUpdate = CALCULATOR.calculateActualHours(calcRequests);

            if (!workItemsToUpdate.isEmpty()) {
                this.uow.registerDirty(workItemsToUpdate);
            }
        }
    }

    // Note: AFTER_DELETE not needed - cascade delete handles share cleanup
}

