     1→/**
     2→ * @description Service class for managing Apex Managed Sharing for Projects and Work Items
     3→ * Uses without sharing to allow share record creation for Community Plus users
     4→ * @author Claude Code
     5→ * @date 2025-10-21
     6→ */
     7→public without sharing class SharingService {
     8→    // Recursion control
     9→    private static Boolean isRecalculating = false;
    10→
    11→    /**
    12→     * @description Recalculates sharing for Projects and their Work Items
    13→     * Uses Resource Type Template Access Level to determine Work Item access
    14→     * Project Managers always get Edit on Projects and Work Items
    15→     * @param projectIds Set of Project IDs to recalculate sharing for
    16→     */
    17→    public static void recalculateProjectSharing(Set<Id> projectIds) {
    18→        if (projectIds == null) {
    19→            return;
    20→        }
    21→
    22→        projectIds.remove(null);
    23→
    24→        if (projectIds.isEmpty()) {
    25→            return;
    26→        }
    27→
    28→        // Prevent recursion
    29→        if (isRecalculating) {
    30→            System.debug(LoggingLevel.WARN, 'Sharing recalculation already in progress, skipping recursive call');
    31→            return;
    32→        }
    33→
    34→        try {
    35→            isRecalculating = true;
    36→
    37→            // Delete existing shares with Resource_Access__c RowCause
    38→            deleteExistingShares(projectIds);
    39→
    40→            // Build new shares - separate lists for different object types to avoid chunking issues
    41→            List<Project__Share> projectSharesToInsert = new List<Project__Share>();
    42→            List<Work_Item__Share> workItemSharesToInsert = new List<Work_Item__Share>();
    43→
    44→            // Query Projects with Manager  // TODO: Move to WI query
    45→            Map<Id, Project__c> projectMap = new Map<Id, Project__c>(
    46→                [
    47→                    SELECT Id, Project_Manager__c
    48→                    FROM Project__c
    49→                    WHERE Id IN :projectIds
    50→                ]
    51→            );
    52→
    53→            // Query all Resources for these Projects
    54→            List<Resource_Assignment__c> resources = [
    55→                SELECT Id, Project__c, Resource_User__c, Access_Level__c
    56→                FROM Resource_Assignment__c
    57→                WHERE Project__c IN :projectIds AND Resource_User__c != NULL
    58→            ];
    59→
    60→            // Query all Work Items for these Projects
    61→            Map<Id, List<Work_Item__c>> workItemsByProject = new Map<Id, List<Work_Item__c>>();
    62→            for (Work_Item__c wi : [
    63→                SELECT Id, Project__c, OwnerId
    64→                FROM Work_Item__c
    65→                WHERE Project__c IN :projectIds
    66→            ]) {
    67→                if (!workItemsByProject.containsKey(wi.Project__c)) {
    68→                    workItemsByProject.put(wi.Project__c, new List<Work_Item__c>());
    69→                }
    70→                workItemsByProject.get(wi.Project__c).add(wi);
    71→            }
    72→
    73→            // Share Projects with Managers (Edit) and Work Items (Edit)
    74→            for (Project__c proj : projectMap.values()) {
    75→                if (proj.Project_Manager__c != null) {
    76→                    // Share Project with Manager (Edit)
    77→                    Project__Share projShare = new Project__Share();
    78→                    projShare.ParentId = proj.Id;
    79→                    projShare.UserOrGroupId = proj.Project_Manager__c;
    80→                    projShare.AccessLevel = 'Edit';
    81→                    projShare.RowCause = Schema.Project__Share.RowCause.Resource_Access__c;
    82→                    projectSharesToInsert.add(projShare);
    83→
    84→                    // Share ALL Work Items with Manager (Edit)
    85→                    if (workItemsByProject.containsKey(proj.Id)) {
    86→                        for (Work_Item__c wi : workItemsByProject.get(proj.Id)) {
    87→                            Work_Item__Share wiShare = new Work_Item__Share();
    88→                            wiShare.ParentId = wi.Id;
    89→                            wiShare.UserOrGroupId = proj.Project_Manager__c;
    90→                            wiShare.AccessLevel = 'Edit';
    91→                            wiShare.RowCause = Schema.Work_Item__Share.RowCause.Resource_Access__c;
    92→                            workItemSharesToInsert.add(wiShare);
    93→                        }
    94→                    }
    95→                }
    96→            }
    97→
    98→            // Share Projects and Work Items with Resources based on Access Level
    99→            for (Resource_Assignment__c resource : resources) {
   100→                String accessLevel = resource.Access_Level__c;
   101→
   102→                // Default to 'Read Only' if Access Level is not set (shouldn't happen as field is required)
   103→                if (String.isBlank(accessLevel)) {
   104→                    accessLevel = 'Read Only';
   105→                }
   106→
   107→                // All resources get Read access to Project
   108→                Project__Share projShare = new Project__Share();
   109→                projShare.ParentId = resource.Project__c;
   110→                projShare.UserOrGroupId = resource.Resource_User__c;
   111→                projShare.AccessLevel = 'Read';
   112→                projShare.RowCause = Schema.Project__Share.RowCause.Resource_Access__c;
   113→                projectSharesToInsert.add(projShare);
   114→
   115→                // Share Work Items based on Access Level
   116→                if (workItemsByProject.containsKey(resource.Project__c)) {
   117→                    if (accessLevel == 'Read Only') {
   118→                        // Read Only: Share all Work Items with Read access
   119→                        for (Work_Item__c wi : workItemsByProject.get(resource.Project__c)) {
   120→                            Work_Item__Share wiShare = new Work_Item__Share();
   121→                            wiShare.ParentId = wi.Id;
   122→                            wiShare.UserOrGroupId = resource.Resource_User__c;
   123→                            wiShare.AccessLevel = 'Read';
   124→                            wiShare.RowCause = Schema.Work_Item__Share.RowCause.Resource_Access__c;
   125→                            workItemSharesToInsert.add(wiShare);
   126→                        }
   127→                    } else if (accessLevel == 'Read/Write') {
   128→                        // Read/Write: Share all Work Items with Edit access
   129→                        for (Work_Item__c wi : workItemsByProject.get(resource.Project__c)) {
   130→                            Work_Item__Share wiShare = new Work_Item__Share();
   131→                            wiShare.ParentId = wi.Id;
   132→                            wiShare.UserOrGroupId = resource.Resource_User__c;
   133→                            wiShare.AccessLevel = 'Edit';
   134→                            wiShare.RowCause = Schema.Work_Item__Share.RowCause.Resource_Access__c;
   135→                            workItemSharesToInsert.add(wiShare);
   136→                        }
   137→                    }
   138→                    // No Access: No Work Item shares created (handled by Work Item Assignment)
   139→                }
   140→            }
   141→
   142→            // Insert shares in batches by object type to avoid chunking limits
   143→            insertSharesInBatches(projectSharesToInsert, 'Project');
   144→            insertSharesInBatches(workItemSharesToInsert, 'Work Item');
   145→        } finally {
   146→            isRecalculating = false;
   147→        }
   148→    }
   149→
   150→    /**
   151→     * @description Insert sharing records in batches to avoid chunking limits
   152→     * Salesforce has a 10-chunk limit per DML operation
   153→     * @param shares List of share records to insert
   154→     * @param objectLabel Label for logging purposes
   155→     */
   156→    private static void insertSharesInBatches(List<SObject> shares, String objectLabel) {
   157→        if (shares.isEmpty()) {
   158→            return;
   159→        }
   160→
   161→        Integer batchSize = 500; // Safe batch size to avoid chunking issues
   162→        Integer totalBatches = (Integer) Math.ceil((Decimal) shares.size() / batchSize);
   163→
   164→        for (Integer i = 0; i < totalBatches; i++) {
   165→            Integer startIdx = i * batchSize;
   166→            Integer endIdx = Math.min(startIdx + batchSize, shares.size());
   167→            List<SObject> batch = new List<SObject>();
   168→
   169→            for (Integer j = startIdx; j < endIdx; j++) {
   170→                batch.add(shares[j]);
   171→            }
   172→
   173→            // Insert batch with partial success allowed
   174→            Database.SaveResult[] results = Database.insert(batch, false);
   175→
   176→            // Log any errors
   177→            for (Integer j = 0; j < results.size(); j++) {
   178→                if (!results[j].isSuccess()) {
   179→                    for (Database.Error err : results[j].getErrors()) {
   180→                        System.debug(
   181→                            LoggingLevel.ERROR,
   182→                            'Error inserting ' + objectLabel + ' share (batch ' + (i + 1) + '/' + totalBatches + '): ' + err.getMessage() + ' for record: ' + batch[j]
   183→                        );
   184→                    }
   185→                }
   186→            }
   187→        }
   188→    }
   189→
   190→    // ==================== INCREMENTAL SHARING METHODS ====================
   191→
   192→    /**
   193→     * @description Add sharing for newly created Resource Assignments (Incremental)
   194→     * Only creates shares for the specific resources being added
   195→     * @param resourceAssignmentIds Set of new Resource Assignment IDs
   196→     */
   197→    public static void addResourceSharing(Set<Id> resourceAssignmentIds) {
   198→        if (resourceAssignmentIds == null || resourceAssignmentIds.isEmpty()) {
   199→            return;
   200→        }
   201→
   202→        // Query the new resource assignments with project and access level info
   203→        List<Resource_Assignment__c> resources = [
   204→            SELECT Id, Project__c, Resource_User__c, Access_Level__c, Project__r.Project_Manager__c
   205→            FROM Resource_Assignment__c
   206→            WHERE Id IN :resourceAssignmentIds AND Resource_User__c != NULL
   207→        ];
   208→
   209→        if (resources.isEmpty()) {
   210→            return;
   211→        }
   212→
   213→        // Get all project IDs to query work items
   214→        Set<Id> projectIds = new Set<Id>();
   215→        for (Resource_Assignment__c resource : resources) {
   216→            projectIds.add(resource.Project__c);
   217→        }
   218→
   219→        // Query all Work Items for these Projects
   220→        Map<Id, List<Work_Item__c>> workItemsByProject = new Map<Id, List<Work_Item__c>>();
   221→        for (Work_Item__c wi : [
   222→            SELECT Id, Project__c
   223→            FROM Work_Item__c
   224→            WHERE Project__c IN :projectIds
   225→        ]) {
   226→            if (!workItemsByProject.containsKey(wi.Project__c)) {
   227→                workItemsByProject.put(wi.Project__c, new List<Work_Item__c>());
   228→            }
   229→            workItemsByProject.get(wi.Project__c).add(wi);
   230→        }
   231→
   232→        List<Project__Share> projectSharesToInsert = new List<Project__Share>();
   233→        List<Work_Item__Share> workItemSharesToInsert = new List<Work_Item__Share>();
   234→
   235→        // Create shares for each resource
   236→        for (Resource_Assignment__c resource : resources) {
   237→            String accessLevel = String.isBlank(resource.Access_Level__c) ? 'Read Only' : resource.Access_Level__c;
   238→
   239→            // All resources get Read access to Project
   240→            Project__Share projShare = new Project__Share();
   241→            projShare.ParentId = resource.Project__c;
   242→            projShare.UserOrGroupId = resource.Resource_User__c;
   243→            projShare.AccessLevel = 'Read';
   244→            projShare.RowCause = Schema.Project__Share.RowCause.Resource_Access__c;
   245→            projectSharesToInsert.add(projShare);
   246→
   247→            // Share Work Items based on Access Level
   248→            if (workItemsByProject.containsKey(resource.Project__c)) {
   249→                List<Work_Item__c> workItems = workItemsByProject.get(resource.Project__c);
   250→
   251→                if (accessLevel == 'Read Only') {
   252→                    // Read Only: Share all Work Items with Read access
   253→                    for (Work_Item__c wi : workItems) {
   254→                        Work_Item__Share wiShare = new Work_Item__Share();
   255→                        wiShare.ParentId = wi.Id;
   256→                        wiShare.UserOrGroupId = resource.Resource_User__c;
   257→                        wiShare.AccessLevel = 'Read';
   258→                        wiShare.RowCause = Schema.Work_Item__Share.RowCause.Resource_Access__c;
   259→                        workItemSharesToInsert.add(wiShare);
   260→                    }
   261→                } else if (accessLevel == 'Read/Write') {
   262→                    // Read/Write: Share all Work Items with Edit access
   263→                    for (Work_Item__c wi : workItems) {
   264→                        Work_Item__Share wiShare = new Work_Item__Share();
   265→                        wiShare.ParentId = wi.Id;
   266→                        wiShare.UserOrGroupId = resource.Resource_User__c;
   267→                        wiShare.AccessLevel = 'Edit';
   268→                        wiShare.RowCause = Schema.Work_Item__Share.RowCause.Resource_Access__c;
   269→                        workItemSharesToInsert.add(wiShare);
   270→                    }
   271→                }
   272→                // No Access: No Work Item shares created
   273→            }
   274→        }
   275→
   276→        // Insert shares in batches
   277→        insertSharesInBatches(projectSharesToInsert, 'Project');
   278→        insertSharesInBatches(workItemSharesToInsert, 'Work Item');
   279→    }
