/**
 * @description Service class for managing Apex Managed Sharing for Projects and Work Items
 * Uses without sharing to allow share record creation for Community Plus users
 * @author Claude Code
 * @date 2025-10-21
 */
public without sharing class SharingService {
    // Recursion control
    private static Boolean isRecalculating = false;

    /**
     * @description Recalculates sharing for Projects and their Work Items
     * Uses Resource Type Template Access Level to determine Work Item access
     * Project Managers always get Edit on Projects and Work Items
     * @param projectIds Set of Project IDs to recalculate sharing for
     */
    public static void recalculateProjectSharing(Set<Id> projectIds) {
        if (projectIds == null) {
            return;
        }

        projectIds.remove(null);

        if (projectIds.isEmpty()) {
            return;
        }

        // Prevent recursion
        if (isRecalculating) {
            System.debug(LoggingLevel.WARN, 'Sharing recalculation already in progress, skipping recursive call');
            return;
        }

        try {
            isRecalculating = true;

            // Delete existing shares with Resource_Access__c RowCause
            deleteExistingShares(projectIds);

            // Build new shares - separate lists for different object types to avoid chunking issues
            List<Project__Share> projectSharesToInsert = new List<Project__Share>();
            List<Work_Item__Share> workItemSharesToInsert = new List<Work_Item__Share>();

            // Query Projects with Manager  // TODO: Move to WI query
            Map<Id, Project__c> projectMap = new Map<Id, Project__c>(
                [
                    SELECT Id, Project_Manager__c
                    FROM Project__c
                    WHERE Id IN :projectIds
                ]
            );

            // Query all Resources for these Projects
            List<Resource_Assignment__c> resources = [
                SELECT Id, Project__c, Resource_User__c, Access_Level__c
                FROM Resource_Assignment__c
                WHERE Project__c IN :projectIds AND Resource_User__c != NULL
            ];

            // Query all Work Items for these Projects
            Map<Id, List<Work_Item__c>> workItemsByProject = new Map<Id, List<Work_Item__c>>();
            for (Work_Item__c wi : [
                SELECT Id, Project__c, OwnerId
                FROM Work_Item__c
                WHERE Project__c IN :projectIds
            ]) {
                if (!workItemsByProject.containsKey(wi.Project__c)) {
                    workItemsByProject.put(wi.Project__c, new List<Work_Item__c>());
                }
                workItemsByProject.get(wi.Project__c).add(wi);
            }

            // Share Projects with Managers (Edit) and Work Items (Edit)
            for (Project__c proj : projectMap.values()) {
                if (proj.Project_Manager__c != null) {
                    // Share Project with Manager (Edit)
                    Project__Share projShare = new Project__Share();
                    projShare.ParentId = proj.Id;
                    projShare.UserOrGroupId = proj.Project_Manager__c;
                    projShare.AccessLevel = 'Edit';
                    projShare.RowCause = Schema.Project__Share.RowCause.Resource_Access__c;
                    projectSharesToInsert.add(projShare);

                    // Share ALL Work Items with Manager (Edit)
                    if (workItemsByProject.containsKey(proj.Id)) {
                        for (Work_Item__c wi : workItemsByProject.get(proj.Id)) {
                            Work_Item__Share wiShare = new Work_Item__Share();
                            wiShare.ParentId = wi.Id;
                            wiShare.UserOrGroupId = proj.Project_Manager__c;
                            wiShare.AccessLevel = 'Edit';
                            wiShare.RowCause = Schema.Work_Item__Share.RowCause.Resource_Access__c;
                            workItemSharesToInsert.add(wiShare);
                        }
                    }
                }
            }

            // Share Projects and Work Items with Resources based on Access Level
            for (Resource_Assignment__c resource : resources) {
                String accessLevel = resource.Access_Level__c;

                // Default to 'Read Only' if Access Level is not set (shouldn't happen as field is required)
                if (String.isBlank(accessLevel)) {
                    accessLevel = 'Read Only';
                }

                // All resources get Read access to Project
                Project__Share projShare = new Project__Share();
                projShare.ParentId = resource.Project__c;
                projShare.UserOrGroupId = resource.Resource_User__c;
                projShare.AccessLevel = 'Read';
                projShare.RowCause = Schema.Project__Share.RowCause.Resource_Access__c;
                projectSharesToInsert.add(projShare);

                // Share Work Items based on Access Level
                if (workItemsByProject.containsKey(resource.Project__c)) {
                    if (accessLevel == 'Read Only') {
                        // Read Only: Share all Work Items with Read access
                        for (Work_Item__c wi : workItemsByProject.get(resource.Project__c)) {
                            Work_Item__Share wiShare = new Work_Item__Share();
                            wiShare.ParentId = wi.Id;
                            wiShare.UserOrGroupId = resource.Resource_User__c;
                            wiShare.AccessLevel = 'Read';
                            wiShare.RowCause = Schema.Work_Item__Share.RowCause.Resource_Access__c;
                            workItemSharesToInsert.add(wiShare);
                        }
                    } else if (accessLevel == 'Read/Write') {
                        // Read/Write: Share all Work Items with Edit access
                        for (Work_Item__c wi : workItemsByProject.get(resource.Project__c)) {
                            Work_Item__Share wiShare = new Work_Item__Share();
                            wiShare.ParentId = wi.Id;
                            wiShare.UserOrGroupId = resource.Resource_User__c;
                            wiShare.AccessLevel = 'Edit';
                            wiShare.RowCause = Schema.Work_Item__Share.RowCause.Resource_Access__c;
                            workItemSharesToInsert.add(wiShare);
                        }
                    }
                    // No Access: No Work Item shares created (handled by Work Item Assignment)
                }
            }

            // Insert shares in batches by object type to avoid chunking limits
            insertSharesInBatches(projectSharesToInsert, 'Project');
            insertSharesInBatches(workItemSharesToInsert, 'Work Item');
        } finally {
            isRecalculating = false;
        }
    }

    /**
     * @description Insert sharing records in batches to avoid chunking limits
     * Salesforce has a 10-chunk limit per DML operation
     * @param shares List of share records to insert
     * @param objectLabel Label for logging purposes
     */
    private static void insertSharesInBatches(List<SObject> shares, String objectLabel) {
        if (shares.isEmpty()) {
            return;
        }

        Integer batchSize = 500; // Safe batch size to avoid chunking issues
        Integer totalBatches = (Integer) Math.ceil((Decimal) shares.size() / batchSize);

        for (Integer i = 0; i < totalBatches; i++) {
            Integer startIdx = i * batchSize;
            Integer endIdx = Math.min(startIdx + batchSize, shares.size());
            List<SObject> batch = new List<SObject>();

            for (Integer j = startIdx; j < endIdx; j++) {
                batch.add(shares[j]);
            }

            // Insert batch with partial success allowed
            Database.SaveResult[] results = Database.insert(batch, false);

            // Log any errors
            for (Integer j = 0; j < results.size(); j++) {
                if (!results[j].isSuccess()) {
                    for (Database.Error err : results[j].getErrors()) {
                        System.debug(
                            LoggingLevel.ERROR,
                            'Error inserting ' + objectLabel + ' share (batch ' + (i + 1) + '/' + totalBatches + '): ' + err.getMessage() + ' for record: ' + batch[j]
                        );
                    }
                }
            }
        }
    }

    // ==================== INCREMENTAL SHARING METHODS ====================

    /**
     * @description Add sharing for newly created Resource Assignments (Incremental)
     * Only creates shares for the specific resources being added
     * @param resourceAssignmentIds Set of new Resource Assignment IDs
     */
    public static void addResourceSharing(Set<Id> resourceAssignmentIds) {
        if (resourceAssignmentIds == null || resourceAssignmentIds.isEmpty()) {
            return;
        }

        // Query the new resource assignments with project and access level info
        List<Resource_Assignment__c> resources = [
            SELECT Id, Project__c, Resource_User__c, Access_Level__c, Project__r.Project_Manager__c
            FROM Resource_Assignment__c
            WHERE Id IN :resourceAssignmentIds AND Resource_User__c != NULL
        ];

        if (resources.isEmpty()) {
            return;
        }

        // Get all project IDs to query work items
        Set<Id> projectIds = new Set<Id>();
        for (Resource_Assignment__c resource : resources) {
            projectIds.add(resource.Project__c);
        }

        // Query all Work Items for these Projects
        Map<Id, List<Work_Item__c>> workItemsByProject = new Map<Id, List<Work_Item__c>>();
        for (Work_Item__c wi : [
            SELECT Id, Project__c
            FROM Work_Item__c
            WHERE Project__c IN :projectIds
        ]) {
            if (!workItemsByProject.containsKey(wi.Project__c)) {
                workItemsByProject.put(wi.Project__c, new List<Work_Item__c>());
            }
            workItemsByProject.get(wi.Project__c).add(wi);
        }

        List<Project__Share> projectSharesToInsert = new List<Project__Share>();
        List<Work_Item__Share> workItemSharesToInsert = new List<Work_Item__Share>();

        // Create shares for each resource
        for (Resource_Assignment__c resource : resources) {
            String accessLevel = String.isBlank(resource.Access_Level__c) ? 'Read Only' : resource.Access_Level__c;

            // All resources get Read access to Project
            Project__Share projShare = new Project__Share();
            projShare.ParentId = resource.Project__c;
            projShare.UserOrGroupId = resource.Resource_User__c;
            projShare.AccessLevel = 'Read';
            projShare.RowCause = Schema.Project__Share.RowCause.Resource_Access__c;
            projectSharesToInsert.add(projShare);

            // Share Work Items based on Access Level
            if (workItemsByProject.containsKey(resource.Project__c)) {
                List<Work_Item__c> workItems = workItemsByProject.get(resource.Project__c);

                if (accessLevel == 'Read Only') {
                    // Read Only: Share all Work Items with Read access
                    for (Work_Item__c wi : workItems) {
                        Work_Item__Share wiShare = new Work_Item__Share();
                        wiShare.ParentId = wi.Id;
                        wiShare.UserOrGroupId = resource.Resource_User__c;
                        wiShare.AccessLevel = 'Read';
                        wiShare.RowCause = Schema.Work_Item__Share.RowCause.Resource_Access__c;
                        workItemSharesToInsert.add(wiShare);
                    }
                } else if (accessLevel == 'Read/Write') {
                    // Read/Write: Share all Work Items with Edit access
                    for (Work_Item__c wi : workItems) {
                        Work_Item__Share wiShare = new Work_Item__Share();
                        wiShare.ParentId = wi.Id;
                        wiShare.UserOrGroupId = resource.Resource_User__c;
                        wiShare.AccessLevel = 'Edit';
                        wiShare.RowCause = Schema.Work_Item__Share.RowCause.Resource_Access__c;
                        workItemSharesToInsert.add(wiShare);
                    }
                }
                // No Access: No Work Item shares created
            }
        }

        // Insert shares in batches
        insertSharesInBatches(projectSharesToInsert, 'Project');
        insertSharesInBatches(workItemSharesToInsert, 'Work Item');
    }

    /**
     * @description Update sharing when Resource Assignment is modified (Incremental)
     * Handles changes to Resource_User__c or Access_Level__c
     * @param resourceAssignmentIds Set of modified Resource Assignment IDs
     * @param oldMap Map of old Resource Assignment records
     */
    public static void updateResourceSharing(Set<Id> resourceAssignmentIds, Map<Id, Resource_Assignment__c> oldMap) {
        if (resourceAssignmentIds == null || resourceAssignmentIds.isEmpty()) {
            return;
        }

        // Query the updated resource assignments
        List<Resource_Assignment__c> resources = [
            SELECT Id, Project__c, Resource_User__c, Access_Level__c
            FROM Resource_Assignment__c
            WHERE Id IN :resourceAssignmentIds
        ];

        Set<Id> resourcesToRemove = new Set<Id>();
        Set<Id> resourcesToAdd = new Set<Id>();

        for (Resource_Assignment__c resource : resources) {
            Resource_Assignment__c oldResource = oldMap.get(resource.Id);

            // If user changed or access level changed, we need to update shares
            if (resource.Resource_User__c != oldResource.Resource_User__c || resource.Access_Level__c != oldResource.Access_Level__c) {
                // Remove old shares and add new ones
                resourcesToRemove.add(resource.Id);
                resourcesToAdd.add(resource.Id);
            }
        }

        // Remove old shares first, then add new ones
        if (!resourcesToRemove.isEmpty()) {
            Map<Id, Resource_Assignment__c> oldResourceMap = new Map<Id, Resource_Assignment__c>();
            for (Id resourceId : resourcesToRemove) {
                oldResourceMap.put(resourceId, oldMap.get(resourceId));
            }
            removeResourceSharingIncremental(resourcesToRemove, oldResourceMap);
        }

        if (!resourcesToAdd.isEmpty()) {
            addResourceSharing(resourcesToAdd);
        }
    }

    /**
     * @description Remove sharing for deleted Resource Assignments (Incremental)
     * Only deletes shares for the specific resources being removed
     * @param resourceAssignmentIds Set of deleted Resource Assignment IDs
     * @param oldResourceMap Map of deleted Resource Assignment records
     */
    public static void removeResourceSharingIncremental(Set<Id> resourceAssignmentIds, Map<Id, Resource_Assignment__c> oldResourceMap) {
        if (resourceAssignmentIds == null || resourceAssignmentIds.isEmpty()) {
            return;
        }

        Set<Id> projectIds = new Set<Id>();
        Set<Id> userIds = new Set<Id>();

        for (Resource_Assignment__c resource : oldResourceMap.values()) {
            if (resource.Resource_User__c != null) {
                projectIds.add(resource.Project__c);
                userIds.add(resource.Resource_User__c);
            }
        }

        if (projectIds.isEmpty() || userIds.isEmpty()) {
            return;
        }

        // Get Work Items for these Projects
        Set<Id> workItemIds = new Set<Id>();
        for (Work_Item__c wi : [
            SELECT Id
            FROM Work_Item__c
            WHERE Project__c IN :projectIds
        ]) {
            workItemIds.add(wi.Id);
        }

        // Delete Project shares for these specific users
        List<Project__Share> projectSharesToDelete = [
            SELECT Id
            FROM Project__Share
            WHERE ParentId IN :projectIds AND UserOrGroupId IN :userIds AND RowCause = :Schema.Project__Share.RowCause.Resource_Access__c
        ];

        if (!projectSharesToDelete.isEmpty()) {
            Database.DeleteResult[] results = Database.delete(projectSharesToDelete, false);
            logDeleteErrors(results, 'Project');
        }

        // Delete Work Item shares for these specific users
        if (!workItemIds.isEmpty()) {
            List<Work_Item__Share> workItemSharesToDelete = [
                SELECT Id
                FROM Work_Item__Share
                WHERE ParentId IN :workItemIds AND UserOrGroupId IN :userIds AND RowCause = :Schema.Work_Item__Share.RowCause.Resource_Access__c
            ];

            if (!workItemSharesToDelete.isEmpty()) {
                Database.DeleteResult[] results = Database.delete(workItemSharesToDelete, false);
                logDeleteErrors(results, 'Work Item');
            }
        }
    }

    /**
     * @description Remove sharing when Resource Assignment is deleted (Legacy - Full Recalc)
     * This method is kept for backward compatibility but triggers full recalc
     * @param oldResourceMap Map of deleted Resource Assignment records
     * @deprecated Use removeResourceSharingIncremental instead
     */
    public static void removeResourceSharing(Map<Id, Resource_Assignment__c> oldResourceMap) {
        if (oldResourceMap == null || oldResourceMap.isEmpty()) {
            return;
        }

        // Use incremental method instead
        removeResourceSharingIncremental(oldResourceMap.keySet(), oldResourceMap);
    }

    /**
     * @description Share newly created Work Items with all Project Resources (Incremental)
     * Shares based on Resource Access Level (Read Only = Read, Read/Write = Edit)
     * Also shares with Project Manager with Edit access
     * @param workItemIds Set of new Work Item IDs
     */
    public static void shareWorkItemWithProjectResources(Set<Id> workItemIds) {
        if (workItemIds == null || workItemIds.isEmpty()) {
            return;
        }

        // Query Work Items with Project info
        Map<Id, Work_Item__c> workItemMap = new Map<Id, Work_Item__c>(
            [
                SELECT Id, Project__c, Project__r.Project_Manager__c
                FROM Work_Item__c
                WHERE Id IN :workItemIds
            ]
        );

        // Get all project IDs
        Set<Id> projectIds = new Set<Id>();
        for (Work_Item__c wi : workItemMap.values()) {
            projectIds.add(wi.Project__c);
        }

        // Query all Resources for these Projects
        List<Resource_Assignment__c> resources = [
            SELECT Id, Project__c, Resource_User__c, Access_Level__c
            FROM Resource_Assignment__c
            WHERE Project__c IN :projectIds AND Resource_User__c != NULL
        ];

        List<Work_Item__Share> workItemSharesToInsert = new List<Work_Item__Share>();

        // Share each Work Item with Project Manager (Edit)
        for (Work_Item__c wi : workItemMap.values()) {
            if (wi.Project__r.Project_Manager__c != null) {
                Work_Item__Share wiShare = new Work_Item__Share();
                wiShare.ParentId = wi.Id;
                wiShare.UserOrGroupId = wi.Project__r.Project_Manager__c;
                wiShare.AccessLevel = 'Edit';
                wiShare.RowCause = Schema.Work_Item__Share.RowCause.Resource_Access__c;
                workItemSharesToInsert.add(wiShare);
            }
        }

        // Share Work Items with Resources based on Access Level
        for (Resource_Assignment__c resource : resources) {
            String accessLevel = String.isBlank(resource.Access_Level__c) ? 'Read Only' : resource.Access_Level__c;

            // Get all work items for this resource's project
            for (Work_Item__c wi : workItemMap.values()) {
                if (wi.Project__c == resource.Project__c) {
                    if (accessLevel == 'Read Only') {
                        // Read Only: Share with Read access
                        Work_Item__Share wiShare = new Work_Item__Share();
                        wiShare.ParentId = wi.Id;
                        wiShare.UserOrGroupId = resource.Resource_User__c;
                        wiShare.AccessLevel = 'Read';
                        wiShare.RowCause = Schema.Work_Item__Share.RowCause.Resource_Access__c;
                        workItemSharesToInsert.add(wiShare);
                    } else if (accessLevel == 'Read/Write') {
                        // Read/Write: Share with Edit access
                        Work_Item__Share wiShare = new Work_Item__Share();
                        wiShare.ParentId = wi.Id;
                        wiShare.UserOrGroupId = resource.Resource_User__c;
                        wiShare.AccessLevel = 'Edit';
                        wiShare.RowCause = Schema.Work_Item__Share.RowCause.Resource_Access__c;
                        workItemSharesToInsert.add(wiShare);
                    }
                    // No Access: No shares created
                }
            }
        }

        // Insert shares in batches
        insertSharesInBatches(workItemSharesToInsert, 'Work Item');
    }

    /**
     * @description Share Work Items with assigned resources via Work Item Assignment
     * Owner gets Edit access, other assignees get Read access
     * @param workItemAssignmentIds Set of Work Item Assignment IDs
     */
    public static void shareWorkItemsWithAssignees(Set<Id> workItemAssignmentIds) {
        if (workItemAssignmentIds == null || workItemAssignmentIds.isEmpty()) {
            return;
        }

        List<SObject> sharesToInsert = new List<SObject>();

        // Query Work Item Assignments with related data
        List<Work_Item_Assignment__c> assignments = [
            SELECT Id, Work_Item__c, Work_Item__r.OwnerId, Resource_Assignment__r.Resource_User__c
            FROM Work_Item_Assignment__c
            WHERE Id IN :workItemAssignmentIds AND Resource_Assignment__r.Resource_User__c != NULL
        ];

        for (Work_Item_Assignment__c assignment : assignments) {
            if (assignment.Resource_Assignment__r.Resource_User__c != null) {
                // Determine access level: Edit if owner, Read otherwise
                String accessLevel = (assignment.Work_Item__r.OwnerId == assignment.Resource_Assignment__r.Resource_User__c) ? 'Edit' : 'Read';

                Work_Item__Share wiShare = new Work_Item__Share();
                wiShare.ParentId = assignment.Work_Item__c;
                wiShare.UserOrGroupId = assignment.Resource_Assignment__r.Resource_User__c;
                wiShare.AccessLevel = accessLevel;
                wiShare.RowCause = Schema.Work_Item__Share.RowCause.Resource_Access__c;
                sharesToInsert.add(wiShare);
            }
        }

        // Insert shares (allow partial success)
        if (!sharesToInsert.isEmpty()) {
            Database.SaveResult[] results = Database.insert(sharesToInsert, false);

            // Log any errors
            for (Integer i = 0; i < results.size(); i++) {
                if (!results[i].isSuccess()) {
                    for (Database.Error err : results[i].getErrors()) {
                        System.debug(LoggingLevel.ERROR, 'Error inserting Work Item Assignment share: ' + err.getMessage());
                    }
                }
            }
        }
    }

    /**
     * @description Remove sharing when Work Item Assignment is deleted
     * @param workItemAssignmentIds Set of Work Item Assignment IDs to remove
     * @param oldAssignments Map of old Work Item Assignment records
     */
    public static void removeWorkItemAssignmentSharing(Set<Id> workItemAssignmentIds, Map<Id, Work_Item_Assignment__c> oldAssignments) {
        if (workItemAssignmentIds == null || workItemAssignmentIds.isEmpty()) {
            return;
        }

        // Get Work Item IDs from old assignments
        Set<Id> workItemIds = new Set<Id>();
        for (Work_Item_Assignment__c assignment : oldAssignments.values()) {
            workItemIds.add(assignment.Work_Item__c);
        }

        // Recalculate sharing for these Work Items based on their Projects
        if (!workItemIds.isEmpty()) {
            Set<Id> projectIds = new Set<Id>();
            for (Work_Item__c wi : [
                SELECT Project__c
                FROM Work_Item__c
                WHERE Id IN :workItemIds
            ]) {
                projectIds.add(wi.Project__c);
            }

            if (!projectIds.isEmpty()) {
                recalculateProjectSharing(projectIds);
            }
        }
    }

    /**
     * @description Delete existing shares for Projects and their Work Items
     * Only deletes shares with Resource_Access__c RowCause
     * Deletes by object type separately to avoid chunking limits
     * @param projectIds Set of Project IDs
     */
    private static void deleteExistingShares(Set<Id> projectIds) {
        // Delete Project shares separately
        List<Project__Share> projectSharesToDelete = [
            SELECT Id
            FROM Project__Share
            WHERE ParentId IN :projectIds AND RowCause = :Schema.Project__Share.RowCause.Resource_Access__c
        ];

        if (!projectSharesToDelete.isEmpty()) {
            Database.DeleteResult[] results = Database.delete(projectSharesToDelete, false);
            logDeleteErrors(results, 'Project');
        }

        // Get Work Items for these Projects
        Set<Id> workItemIds = new Set<Id>();
        for (Work_Item__c wi : [
            SELECT Id
            FROM Work_Item__c
            WHERE Project__c IN :projectIds
        ]) {
            workItemIds.add(wi.Id);
        }

        // Delete Work Item shares separately
        if (!workItemIds.isEmpty()) {
            List<Work_Item__Share> workItemSharesToDelete = [
                SELECT Id
                FROM Work_Item__Share
                WHERE ParentId IN :workItemIds AND RowCause = :Schema.Work_Item__Share.RowCause.Resource_Access__c
            ];

            if (!workItemSharesToDelete.isEmpty()) {
                Database.DeleteResult[] results = Database.delete(workItemSharesToDelete, false);
                logDeleteErrors(results, 'Work Item');
            }
        }
    }

    /**
     * @description Log delete errors
     * @param results Delete results to check
     * @param objectLabel Label for logging
     */
    private static void logDeleteErrors(Database.DeleteResult[] results, String objectLabel) {
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                for (Database.Error err : results[i].getErrors()) {
                    System.debug(LoggingLevel.ERROR, 'Error deleting ' + objectLabel + ' share: ' + err.getMessage());
                }
            }
        }
    }
}

