public with sharing class WorkItemHoursCalculator {
    /**
     * Calculate and update actual hours for work items and all their ancestors
     * Actual Hours = Total Logged Hours (direct time entries) + Sum of all children's Actual Hours (recursive)
     */
    public List<Work_Item__c> calculateActualHours(Set<Id> workItemIds) {
        // Get work items with their logged hours and parent IDs
        List<Work_Item__c> workItemsQueried = [
            SELECT Total_Logged_Hours__c, Parent_Work_Item__c
            FROM Work_Item__c
            WHERE Id IN :workItemIds
            WITH USER_MODE
        ];

        // Get all children and their actual hours (which already include their descendants)
        Map<Id, List<Work_Item__c>> childrenByParentIds = new Map<Id, List<Work_Item__c>>();
        for (Work_Item__c child : [
            SELECT Parent_Work_Item__c, Actual_Hours__c
            FROM Work_Item__c
            WHERE Parent_Work_Item__c IN :workItemIds
            WITH USER_MODE
        ]) {
            if (!childrenByParentIds.containsKey(child.Parent_Work_Item__c)) {
                childrenByParentIds.put(child.Parent_Work_Item__c, new List<Work_Item__c>());
            }
            childrenByParentIds.get(child.Parent_Work_Item__c).add(child);
        }

        // Calculate and UPDATE actual hours for each work item (do the update here, not in Flow)
        List<Work_Item__c> workItemsToUpdate = new List<Work_Item__c>();
        Set<Id> parentIdsToUpdate = new Set<Id>();
        List<Work_Item__c> results = new List<Work_Item__c>();

        for (Work_Item__c workItem : workItemsQueried) {
            Work_Item__c result = new Work_Item__c(Id = workItem.Id);

            // Start with direct logged hours (from time entries on this work item)
            result.Actual_Hours__c = workItem.Total_Logged_Hours__c ?? 0;

            // Add children's actual hours (which include their entire subtree)
            if (childrenByParentIds.containsKey(workItem.Id)) {
                for (Work_Item__c child : childrenByParentIds.get(workItem.Id)) {
                    if (child.Actual_Hours__c != null) {
                        result.Actual_Hours__c += child.Actual_Hours__c;
                    }
                }
            }

            // Update the work item's actual hours
            workItem.Actual_Hours__c = result.Actual_Hours__c;
            workItemsToUpdate.add(workItem);

            result.Actual_Hours__c = result.Actual_Hours__c;
            results.add(result);

            // Track parent for cascade update
            if (workItem.Parent_Work_Item__c != null) {
