    /**
     * Recursively update all ancestor work items' Actual_Hours__c
     * This ensures hours cascade up the entire hierarchy
     */
    private static void updateAncestors(Set<Id> workItemIds) {
        if (workItemIds == null || workItemIds.isEmpty()) {
            return;
        }

        // Get parent work items with their current data
        Map<Id, Work_Item__c> parentsMap = new Map<Id, Work_Item__c>(
            [
                SELECT Total_Logged_Hours__c, Parent_Work_Item__c
                FROM Work_Item__c
                WHERE Id IN :workItemIds
                WITH USER_MODE
            ]
        );

        if (parentsMap.isEmpty()) {
            return;
        }

        // TODO: Duplicate code - refactor into a shared method
        // Get all children for these parents (to recalculate their totals)
        Map<Id, List<Work_Item__c>> parentToChildrenMap = new Map<Id, List<Work_Item__c>>();
        for (Work_Item__c child : [
            SELECT Parent_Work_Item__c, Actual_Hours__c
            FROM Work_Item__c
            WHERE Parent_Work_Item__c IN :workItemIds
            WITH USER_MODE
        ]) {
            if (!parentToChildrenMap.containsKey(child.Parent_Work_Item__c)) {
                parentToChildrenMap.put(child.Parent_Work_Item__c, new List<Work_Item__c>());
            }
            parentToChildrenMap.get(child.Parent_Work_Item__c).add(child);
        }

        // Calculate new actual hours for each parent
        List<Work_Item__c> parentsToUpdate = new List<Work_Item__c>();
        Set<Id> grandparentIds = new Set<Id>();

        for (Id parentId : parentsMap.keySet()) {
            Work_Item__c parent = parentsMap.get(parentId);

            // Start with direct logged hours
            parent.Actual_Hours__c = parent.Total_Logged_Hours__c ?? 0;

            // Add children's actual hours
            if (parentToChildrenMap.containsKey(parentId)) {
                for (Work_Item__c child : parentToChildrenMap.get(parentId)) {
                    if (child.Actual_Hours__c != null) {
                        parent.Actual_Hours__c += child.Actual_Hours__c;
                    }
                }
            }

            // Update parent's actual hours
            parentsToUpdate.add(parent);

            // Track grandparents for next level update
            if (parent.Parent_Work_Item__c != null) {
                grandparentIds.add(parent.Parent_Work_Item__c);
            }
        }

        // Update parents
        if (!parentsToUpdate.isEmpty()) {
            update as user parentsToUpdate;
        }

        // Recursively update grandparents and above
        if (!grandparentIds.isEmpty()) {
            updateAncestors(grandparentIds);
